import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
/*eslint-disable*/
import { asset_sub_category } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_asset_sub_categories } from "@/mixins/GetAssetSubCategories.js";
import EditSubcategories from "@/components/Asset/Popups/EditSubcategories.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  props: {
    categoriessubAddition: Boolean,
    rowInfo: Object
  },
  components: {
    EditSubcategories,
    SnackBar
  },
  mixins: [get_asset_sub_categories],
  data() {
    return {
      categoriesName: "",
      depreciationCode: "",
      loading: false,
      categoriesdescription: "",
      categoryitems: [],
      maincategories: "",
      depreciationitems: Array.from({
        length: 100
      }, (_, i) => i + 1),
      categoryPrefix: "",
      selectedSubCategory: [],
      selectsub: "",
      loading2: false,
      headers: [{
        title: "Name",
        key: "text",
        sortable: false
      }, {
        title: "Prefix",
        key: "sub_category_prefix",
        sortable: false
      }, {
        title: "Description",
        key: "sub_category_depriciation",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      tableLoading: false,
      fixed: true,
      componentCheck: 0,
      categoriessubEddition: false,
      categoriesItem: {},
      SnackBarComponent: {}
    };
  },
  watch: {
    categoriessubAddition: {
      async handler() {
        if (this.categoriessubAddition == true) {
          this.selectedSubCategory = [];
          this.tableLoading = true;
          this.depreciationCode = this.rowInfo.category_depriciation;
          // console.log(this.rowInfo, "rowInfo");

          await this.get_asset_sub_categories();
          this.tableLoading = false;
          this.fetch_sub_data();
        }
      },
      immediate: true
    }
  },
  methods: {
    fetch_sub_data() {
      // console.log(this.assetSubCategories);
      var filteredArray = this.assetSubCategories.filter(obj => obj.category_id === this.rowInfo.category_id);
      filteredArray.forEach(element => {
        this.selectedSubCategory.push({
          text: element.sub_category_name,
          value: element.sub_category_id,
          sub_category_prefix: element.sub_category_prefix,
          sub_category_depriciation: element.sub_category_depriciation
        });
      });
    },
    open_edit_dailog(item) {
      this.componentCheck = 1;
      this.categoriessubEddition = true;
      this.categoriesItem = item;
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.selectedSubCategory = [];
      this.categoriessubEddition = false;
      await this.get_asset_sub_categories();
      this.tableLoading = false;
      this.fetch_sub_data();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    delete_data(item) {
      this.selectsub = item.value;
      this.loading2 = true;
      this.add_mutation("DELETE_SUBCATEGORY");
    },
    convert_to_uppercase(value) {
      if (value != null || value != "") {
        this.categoryPrefix = value.toUpperCase();
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.categoryPrefix = "";
      this.categoriesName = "";
      // this.$refs.form.reset();
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.loading = true;
        this.add_mutation("CREATE_SUBCATEGORY");
      }
    },
    async add_mutation(value) {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(asset_sub_category, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: value,
            category_id: value == "CREATE_SUBCATEGORY" ? this.rowInfo.category_id : undefined,
            sub_category_name: value == "CREATE_SUBCATEGORY" ? this.categoriesName : undefined,
            sub_category_depriciation: Number(this.depreciationCode),
            sub_category_prefix: value == "CREATE_SUBCATEGORY" ? this.categoryPrefix : undefined,
            sub_category_id: value == "DELETE_SUBCATEGORY" ? this.selectsub : undefined
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.asset_sub_category);
        this.loading2 = false;
        if (response.Status == "SUCCESS") {
          this.selectedSubCategory = [];
          this.tableLoading = true;
          await this.get_asset_sub_categories();
          this.tableLoading = false;
          this.fetch_sub_data();
          this.$emit("successMsg", response.Message);

          // this.$refs.form.reset();
          // this.categoryPrefix = "";
          this.categoryPrefix = "";
          this.categoriesName = "";
          this.$refs.form.resetValidation();
          this.depreciationCode = this.rowInfo.category_depriciation;

          // this.$emit("updaterefesh", "update");
        } else {
          this.loading = false;
          this.loading2 = false;
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.loading2 = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
